import{_ as a}from"./chunks/daily-2026-08-18-cursor-accepted-delivery.DdlWfyRG.js";import{_ as i,C as n,o as s,c as r,E as o,a2 as l}from"./chunks/framework.Cm6XCzck.js";const b=JSON.parse('{"title":"Running an AI Development Team in Cursor: From Requirement to Testable Delivery","description":"","frontmatter":{"title":"Running an AI Development Team in Cursor: From Requirement to Testable Delivery","date":"2026-08-18","column":"digital-employee","category":"daily","article_type":"project-research","edition":"research-center","research_question":"How can multiple Cursor agents become a responsibility-separated, evidence-bearing delivery chain with a human release decision rather than parallel chat sessions?","summary":"The guide turns PM, DEV, OPS, QA, independent EVAL, and human approval into requirement cards, TASKs, REPORTs, rework, and acceptance steps. The goal is accepted delivery, not more agent windows.","item_id":"MANUAL-20260818-CURSOR","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-18-cursor-ai-development-team-cover.webp","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"sources":["research/manual-runs/2026-08-18-guided-article-pipeline-round1/02-source-register.md","research/manual-runs/2026-08-18-guided-article-pipeline-round1/02-fact-matrices.md","research/manual-runs/2026-08-18-guided-article-pipeline-round1/02-article-briefs.md","research/manual-runs/2026-08-18-guided-article-pipeline-round1/02-independent-editorial-review.md"]},"headers":[],"relativePath":"en/digital-employee/2026-08-18-cursor-ai-development-team.md","filePath":"en/digital-employee/2026-08-18-cursor-ai-development-team.md","lastUpdated":1787044313000}'),d={name:"en/digital-employee/2026-08-18-cursor-ai-development-team.md"};function p(c,e,h,u,m,g){const t=n("ArticleCover");return s(),r("div",null,[o(t,{image:"/assets/covers/daily-2026-08-18-cursor-ai-development-team-cover.webp",kicker:"Digital Employee · Project Research",title:"Running an AI Development Team in Cursor: From Requirement to Testable Delivery",summary:"This operating guide turns PM, DEV, OPS, QA, independent EVAL, and human approval into requirement cards, TASKs, REPORTs, rework, and acceptance steps. The goal is accepted delivery—not more agent windows.",version:"MANUAL-20260818-CURSOR",status:"Independent Editorial PASS · 2026-08-18",languageHref:"/zh/digital-employee/2026-08-18-cursor-ai-development-team",languageLabel:"中文"}),e[0]||(e[0]=l(`<h1 id="running-an-ai-development-team-in-cursor-from-requirement-to-testable-delivery" tabindex="-1">Running an AI Development Team in Cursor: From Requirement to Testable Delivery <a class="header-anchor" href="#running-an-ai-development-team-in-cursor-from-requirement-to-testable-delivery" aria-label="Permalink to &quot;Running an AI Development Team in Cursor: From Requirement to Testable Delivery&quot;">​</a></h1><blockquote><p>Four Agent windows produce four parallel conversations. An AI development team begins only when those agents share role contracts, durable artifacts, independent acceptance, and a human release decision.</p></blockquote><p><strong>Reading dependency:</strong> this is the operating guide in a three-part series. Read <a href="/joinwell52/en/engineering/2026-08-18-files-first-multi-agent-governance">the governance argument</a> for the shared work ledger, and <a href="/joinwell52/en/engineering/2026-08-18-fcop-file-state-machine">the protocol implementation</a> for path state, transitions, and atomic publication.</p><p>Send the same feature request to four Cursor Agents. Ask one to implement it, another to write tests, a third to check runtime behavior, and a fourth to review the code. The windows become busy. Soon, each says the work is complete.</p><p>The likely failure is not a difficult algorithm. It is coordination drift. Development changed an interface while testing used the old one. Operations verified a startup path that no longer exists. The reviewer read the implementer’s summary instead of the actual diff and failing cases. Parallelism amplified ambiguity.</p><p>This guide has a narrower goal than building an “autonomous company.” Research Center has already argued that <a href="/joinwell52/en/digital-employee/2026-08-05-verifiable-completion">a worker cannot accept its own completion claim</a>, and its CodeFlowMu case study showed why <a href="/joinwell52/en/engineering/2026-08-06-codeflowmu-multi-agent-fact-checking">roles, fact sources, and decision authority must remain separate</a>. This article turns those existing governance conclusions into a Cursor operating manual. It combines Cursor’s planning, editing, terminal, and diff-review surfaces with the role and artifact model used by CodeFlowMu-open and FCoP.</p><h2 id="first-decide-whether-the-work-needs-a-team" tabindex="-1">First decide whether the work needs a team <a class="header-anchor" href="#first-decide-whether-the-work-needs-a-team" aria-label="Permalink to &quot;First decide whether the work needs a team&quot;">​</a></h2><p>A small fix, one-file edit, or direct question is usually cheaper with one agent. Multiple roles start to help when a task has at least two of these properties:</p><ul><li>implementation, testing, runtime, or deployment responsibilities must be separated;</li><li>another role must independently evaluate the result;</li><li>work spans several sessions or a long period;</li><li>failure should become formal rework rather than another chat reply; or</li><li>a human must approve a risky transition.</li></ul><p><a href="https://www.anthropic.com/engineering/building-effective-agents" target="_blank" rel="noreferrer">Anthropic’s engineering guidance</a> distinguishes single agents from orchestrator-worker and evaluator-optimizer workflows and recommends matching complexity to the problem. Agent count is not the first team metric. A better question is whether every unit of work has one owner, a defined artifact, and an independent completion condition.</p><h2 id="roles-are-decision-boundaries-not-personas" tabindex="-1">Roles are decision boundaries, not personas <a class="header-anchor" href="#roles-are-decision-boundaries-not-personas" aria-label="Permalink to &quot;Roles are decision boundaries, not personas&quot;">​</a></h2><p>The public <a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/README.md" target="_blank" rel="noreferrer">CodeFlowMu-open</a> design uses PM, DEV, OPS, and QA roles, along with an independent EVAL step, FCoP artifacts, PC/PWA views, and human approval. The role names matter only because they allocate authority.</p><blockquote><p><strong>Roles in multi-agent work are not dramatic prompt personas. They exist to allocate decision rights that other roles must not silently assume.</strong></p></blockquote><table tabindex="0"><thead><tr><th>Role</th><th>Owns</th><th>Must not substitute for</th></tr></thead><tbody><tr><td>PM</td><td>requirement clarity, task boundaries, dependencies, acceptance, rework</td><td>DEV’s technical evidence or QA’s release judgment</td></tr><tr><td>DEV</td><td>implementation, local verification, change report</td><td>final approval or unilateral acceptance changes</td></tr><tr><td>OPS</td><td>installation, startup, configuration, logs, runtime boundaries</td><td>functional correctness</td></tr><tr><td>QA</td><td>acceptance tests, regression checks, independent QA REPORT</td><td>a paraphrase of DEV’s test report or an EVAL role</td></tr><tr><td>EVAL</td><td>independent quality and risk observation after PM’s final REPORT</td><td>lifecycle mutation or PM/ADMIN approval</td></tr></tbody></table><p>One person may supervise every role, and the same model may serve different roles in separate sessions. The artifacts and decisions should still remain distinct. A worker report is not a review verdict; local tests are not a release approval.</p><h2 id="step-1-turn-a-request-into-an-acceptance-card" tabindex="-1">Step 1: turn a request into an acceptance card <a class="header-anchor" href="#step-1-turn-a-request-into-an-acceptance-card" aria-label="Permalink to &quot;Step 1: turn a request into an acceptance card&quot;">​</a></h2><p><a href="https://cursor.com/docs/agent/plan-mode" target="_blank" rel="noreferrer">Cursor Plan Mode</a> researches the codebase, asks clarifying questions, and produces a reviewable implementation plan. A plan is useful, but a team still needs a testable contract. Before assigning work, the PM should write something like:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Requirement: Export failed records as CSV</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## User outcome</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">A user can export the currently filtered failures and open the result</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">in a spreadsheet application.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## In scope</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Add a CSV export action and download behavior</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Reuse the current filters</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Preserve Chinese text, commas, quotes, and line breaks</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Out of scope</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> No Excel format</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> No backend query redesign</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> No list-page redesign</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Acceptance</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">1.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Exports work for 0, 1, and 1,000 records.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">2.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Chinese and special characters open correctly in Excel/LibreOffice.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">3.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Only currently filtered records are present.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">4.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Existing list tests do not regress.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">5.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> The diff contains no unrelated refactor.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Required evidence</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> changed-file list</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> test commands and results</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sample CSV containing special characters</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> known limitations</span></span></code></pre></div><p>“Add CSV export” names a feature. The card names an outcome that another party can judge. If an agent cannot determine when to stop from the card, it is not ready for assignment.</p><h2 id="step-2-assign-responsibility-with-separate-tasks" tabindex="-1">Step 2: assign responsibility with separate TASKs <a class="header-anchor" href="#step-2-assign-responsibility-with-separate-tasks" aria-label="Permalink to &quot;Step 2: assign responsibility with separate TASKs&quot;">​</a></h2><p>Do not paste the whole request into every session and hope the agents coordinate. Create related tasks:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TASK-001  PM → DEV  Implement export and unit tests</span></span>
<span class="line"><span>TASK-002  PM → OPS  Verify build, startup, and download path</span></span>
<span class="line"><span>TASK-003  PM → QA   Test all five acceptance criteria independently</span></span></code></pre></div><p>Each task references the same requirement but has its own scope, dependencies, and acceptance conditions. QA should depend on DEV’s report and a testable build. OPS owns runtime evidence rather than feature semantics.</p><p>FCoP filenames and front matter can preserve sender, recipient, parent, priority, and time. Lifecycle paths show whether a task is waiting, active, or under review. The supervisor can inspect the workspace before opening four conversation histories.</p><p><img src="`+a+'" alt="A requirement becomes PM-owned tasks, DEV OPS and QA evidence, a PM decision, and human approval"></p><p><em>Figure 1. A worker&#39;s <code>done</code> is only a completion claim. Independent testing, PM acceptance or rework, side-channel EVAL observation, and human approval remain distinct responsibilities. Source: Research Center synthesis of the CodeFlowMu-open role contract and this article&#39;s workflow.</em></p><h2 id="step-3-execute-in-cursor-but-keep-evidence-outside-chat" tabindex="-1">Step 3: execute in Cursor, but keep evidence outside chat <a class="header-anchor" href="#step-3-execute-in-cursor-but-keep-evidence-outside-chat" aria-label="Permalink to &quot;Step 3: execute in Cursor, but keep evidence outside chat&quot;">​</a></h2><p><a href="https://cursor.com/docs/agent/overview#tools" target="_blank" rel="noreferrer">Cursor Agent tools</a> include code search, file editing, and terminal access. Those tools should produce environmental evidence, not just a narrative of actions.</p><p>A minimum DEV sequence is:</p><ol><li>restate scope and exclusions; raise an ISSUE before guessing;</li><li>inspect relevant code and existing tests;</li><li>implement the smallest coherent change;</li><li>run targeted tests, then related regression tests;</li><li>inspect the diff and remove unrelated changes;</li><li>write a REPORT with changes, commands, results, evidence paths, and risks; and</li><li>submit for review rather than self-archiving.</li></ol><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># REPORT: TASK-001</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Change: added </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`exportFailuresCsv`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> and a list-page export action</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Target tests: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`pnpm test export-csv`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> — 12 passed</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Regression: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`pnpm test failures-list`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> — 28 passed</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Sample: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`artifacts/failures-special-chars.csv`</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Not verified: Safari iOS download behavior</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Diff: 3 files, no unrelated refactor</span></span></code></pre></div><p>Cursor checkpoints are useful for undoing agent changes, but the <a href="https://cursor.com/docs/agent/overview#checkpoints" target="_blank" rel="noreferrer">official documentation</a> says they are stored separately from Git and should be used only to undo Agent changes. Durable evidence still belongs in Git diffs, test output, and project artifacts.</p><h2 id="step-4-make-ops-and-qa-verify-different-facts" tabindex="-1">Step 4: make OPS and QA verify different facts <a class="header-anchor" href="#step-4-make-ops-and-qa-verify-different-facts" aria-label="Permalink to &quot;Step 4: make OPS and QA verify different facts&quot;">​</a></h2><p>OPS should not repeat unit tests. It verifies whether dependencies install, the project builds, the supported startup path works, logs expose failures, and configuration requires manual steps.</p><p>QA starts from the requirement rather than trusting the DEV report. It should cover:</p><ul><li>the normal filtering and export path;</li><li>zero records, special characters, and a large result;</li><li>download or permission failures;</li><li>existing list behavior; and</li><li>unrelated changes in the diff.</li></ul><p><a href="https://cursor.com/learn/reviewing-testing" target="_blank" rel="noreferrer">Cursor&#39;s reviewing and testing guidance</a> recommends watching changes in the diff view and warns that AI-generated code may look correct—even compile and pass existing tests—while still missing edge cases or security issues. That is a review surface, not a review standard. QA should submit criterion-by-criterion evidence in a QA REPORT. PM or a governance role then accepts, creates rework, or escalates. If the decision is written as an FCoP REVIEW, the on-disk enum is <code>approved</code>, <code>rejected</code>, <code>needs_changes</code>, <code>abstained</code>, or <code>needs_human</code>—not an editorial PASS/NEEDS REVISION/REJECT label.</p><p>EVAL is a separate side channel. The current <a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/docs/open/release-and-initialization.md" target="_blank" rel="noreferrer">CodeFlowMu-open release and initialization boundary</a> says PM’s final <code>status=done</code> REPORT triggers an independent EVAL observation. EVAL does not mutate lifecycle state or replace PM/ADMIN acceptance.</p><h2 id="step-5-turn-rejection-into-a-better-task" tabindex="-1">Step 5: turn rejection into a better task <a class="header-anchor" href="#step-5-turn-rejection-into-a-better-task" aria-label="Permalink to &quot;Step 5: turn rejection into a better task&quot;">​</a></h2><p>Continue the CSV example. If QA finds that Chinese text is still garbled in Excel, do not send DEV a chat message saying “try again.” Make the failure a traceable rework cycle:</p><ol><li>the QA REPORT names the failed acceptance condition and preserves reproduction evidence;</li><li>PM records <code>needs_changes</code> in a REVIEW or acceptance record and opens an ISSUE when needed;</li><li>PM distinguishes implementation error from specification omission;</li><li>PM creates a child rework TASK;</li><li>the new task narrows scope and adds the missing example; and</li><li>the fix passes through independent validation again.</li></ol><p>This history lets a later review distinguish model failure from a management decision that was never written down.</p><h2 id="step-6-approve-only-from-an-evidence-packet" tabindex="-1">Step 6: approve only from an evidence packet <a class="header-anchor" href="#step-6-approve-only-from-an-evidence-packet" aria-label="Permalink to &quot;Step 6: approve only from an evidence packet&quot;">​</a></h2><p>The human approver does not have to redo every test. They should receive a compact packet containing:</p><ul><li>the requirement and current scope;</li><li>the three task states;</li><li>DEV and OPS reports;</li><li>QA REPORT;</li><li>PM’s acceptance or rework decision;</li><li>an independent EVAL observation after PM’s final REPORT, when available;</li><li>the actual diff;</li><li>test commands and results; and</li><li>unverified risks and rollback instructions.</li></ul><p>One question filters many false completions: <strong>If I merge now, what environmental fact am I relying on, and where do I recover if it fails?</strong></p><blockquote><p><strong>A worker saying “done” is a completion claim, not a delivery. Delivery begins when independent environmental evidence and an authorized review accept that claim.</strong></p></blockquote><p>The CodeFlowMu-open PC/PWA surfaces can index team state, but the UI should not become the source of truth. Evidence remains on disk, in Git, and in the test environment. Claims about the open edition must also respect its documented <a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/docs/open/edition-boundary.md" target="_blank" rel="noreferrer">edition boundary</a>; private production features and roadmap items do not belong in an open-edition tutorial.</p><h2 id="a-minimum-one-day-run" tabindex="-1">A minimum one-day run <a class="header-anchor" href="#a-minimum-one-day-run" aria-label="Permalink to &quot;A minimum one-day run&quot;">​</a></h2><p>You can test the method without deploying a complete platform:</p><table tabindex="0"><thead><tr><th>Time</th><th>Action</th><th>Artifact</th></tr></thead><tbody><tr><td>09:00</td><td>Choose a feature that fits in 2–4 hours</td><td>acceptance card</td></tr><tr><td>09:20</td><td>Split DEV, OPS, and QA responsibilities</td><td>three TASKs</td></tr><tr><td>09:30</td><td>Implement and run targeted tests</td><td>diff + DEV REPORT</td></tr><tr><td>11:00</td><td>Verify build and startup from a clean entry point</td><td>OPS REPORT</td></tr><tr><td>11:30</td><td>Test the acceptance criteria independently</td><td>QA REPORT</td></tr><tr><td>12:00</td><td>Resolve rejection or submit PM’s final result</td><td>rework TASK or PM REPORT</td></tr><tr><td>12:10</td><td>Observe the final result independently</td><td>EVAL observation</td></tr><tr><td>12:20</td><td>Inspect diff, evidence, and risk</td><td>human approve/reject</td></tr></tbody></table><p>Measure four things on the first run:</p><ol><li>How many problems came from unclear requirements rather than coding ability?</li><li>How many report claims linked directly to environmental evidence?</li><li>Did QA find anything missing from DEV’s self-test?</li><li>Did rejection create a clearer, traceable next action?</li></ol><p>Those results say more about team effectiveness than concurrent agent count.</p><h2 id="keep-governance-proportional-to-risk" tabindex="-1">Keep governance proportional to risk <a class="header-anchor" href="#keep-governance-proportional-to-risk" aria-label="Permalink to &quot;Keep governance proportional to risk&quot;">​</a></h2><p>The workflow has costs. On tiny tasks, artifacts can cost more than they save. If every role shares the same context, “independent” review may be self-confirmation. Over-specified acceptance can make agents optimize the checklist while missing the user outcome. Automatically approving every gate turns human oversight into ceremony.</p><p>Scale governance with risk: one agent plus diff review for small fixes; PM and QA for cross-module features; OPS, independent EVAL, and explicit human gates for deployment, security, or data changes.</p><h2 id="from-multiple-windows-to-accepted-delivery" tabindex="-1">From multiple windows to accepted delivery <a class="header-anchor" href="#from-multiple-windows-to-accepted-delivery" aria-label="Permalink to &quot;From multiple windows to accepted delivery&quot;">​</a></h2><p>An AI development team in Cursor is not four agents talking at once. It operationalizes an existing governance conclusion: PM owns task clarity, DEV owns implementation evidence, OPS owns the runtime path, QA owns independent testing, EVAL observes quality and risk from the side, and a human owns final risk.</p><p>Cursor supplies planning, tools, diff review, and checkpoints. CodeFlowMu-open and FCoP supply one way to organize roles and durable artifacts. Together, they do not create an unsupervised company. They create a more useful capability: <strong>a request can become traceable work, a completion claim can be independently tested, and a failure can become a clearer next task.</strong></p><p>That is the first outcome a one-person AI team should pursue.</p><p>If you entered the series here, return to <a href="/joinwell52/en/engineering/2026-08-18-files-first-multi-agent-governance">the governance article</a> to understand the shared ledger, then use <a href="/joinwell52/en/engineering/2026-08-18-fcop-file-state-machine">the state-machine article</a> to verify path state, atomic publication, and test invariants. Together, the three pieces explain why to govern this way, how the protocol behaves, and how a team delivers.</p><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><ul><li><a href="https://cursor.com/docs/agent/plan-mode" target="_blank" rel="noreferrer">Cursor Plan Mode</a></li><li><a href="https://cursor.com/docs/agent/overview#tools" target="_blank" rel="noreferrer">Cursor Agent tools</a></li><li><a href="https://cursor.com/learn/reviewing-testing" target="_blank" rel="noreferrer">Cursor reviewing and testing</a></li><li><a href="https://cursor.com/docs/agent/overview#checkpoints" target="_blank" rel="noreferrer">Cursor Checkpoints</a></li><li><a href="https://www.anthropic.com/engineering/building-effective-agents" target="_blank" rel="noreferrer">Anthropic, Building Effective Agents</a></li><li><a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/README.md" target="_blank" rel="noreferrer">CodeFlowMu-open README</a></li><li><a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/docs/open/edition-boundary.md" target="_blank" rel="noreferrer">CodeFlowMu-open edition boundary</a></li><li><a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/docs/open/release-and-initialization.md" target="_blank" rel="noreferrer">CodeFlowMu-open release and initialization boundary</a></li><li><a href="https://github.com/joinwell52-AI/FCoP/blob/a859e6747fe6e5e2d686e0114c77774726d7f748/spec/fcop-v3-spec.md" target="_blank" rel="noreferrer">FCoP v3 specification</a></li></ul>',64))])}const v=i(d,[["render",p]]);export{b as __pageData,v as default};
